// Replay exact stored Sample objects; child node weights must not be multiplied again.
use color_eyre::{eyre::{ensure,eyre},Result};
use figment::{providers::Serialized,Figment};
use gammaloop_api::{commands::set::SetArgs,StateLoadOption};
use gammalooprs::{initialisation::initialise,integrate::IntegrationState,integrands::process::{cross_section::CrossSectionGraphTerm,GraphTerm,ProcessIntegrand,SamplingChannelId},settings::runtime::Precision,utils::{ArbPrec,F,FloatLike,QuadFloat}};
use serde_json::{json,Value};
use spenso::algebra::complex::Complex;
use symbolica::numerical_integration::Sample;
use std::{env,fs,time::Instant};
fn path(sample:&Sample<F<f64>>)->Result<(Vec<usize>,Vec<f64>,Vec<Value>)>{
 let mut s=sample;let mut ids=Vec::new();let mut factors=Vec::new();
 loop{match s{Sample::Discrete(w,id,Some(child))=>{ids.push(*id);factors.push(json!({"kind":"discrete","index":id,"subtree_weight":w.0,"conditional_inverse_probability":w.0/child.get_weight().0}));s=child;},Sample::Continuous(w,x)=>{factors.push(json!({"kind":"continuous","weight":w.0}));return Ok((ids,x.iter().map(|v|v.0).collect(),factors));},_=>return Err(eyre!("expected complete nested discrete/continuous Sample"))}}
}
fn mapped<T:FloatLike>(term:&CrossSectionGraphTerm,id:usize,cube:&[f64])->Result<Value>{
 let native=cube.iter().map(|v|T::from_f64_exact_binary(*v)).collect::<Vec<_>>();let b=term.sampling_setup().sampling_bridge::<T>()?;let p=b.forward(SamplingChannelId(id),&native)?;
 Ok(json!({"channel_id":id,"name":p.channel_name,"raw_momenta":p.raw_coordinates.iter().map(|v|F(v.clone()).to_string()).collect::<Vec<_>>(),"map_jacobian":F(p.map.jacobian.clone()).to_string(),"inverse_jacobian":F(p.map.inverse_jacobian.clone()).to_string(),"partition":p.partition.weights.iter().map(|v|F(v.clone()).to_string()).collect::<Vec<_>>(),"selected_factor":F(p.selected_factor()?).to_string(),"diagnostics":p.map.diagnostics,"note":"diagnostic factors already folded into physical result; never multiply them again"}))
}
fn main()->Result<()>{
 initialise()?;let args=env::args().skip(1).collect::<Vec<_>>();ensure!(args.len()==3,"manifest pilot_directory output_directory");let manifest:Value=serde_json::from_str(&fs::read_to_string(&args[0])?)?;let start=Instant::now();
 let mut loaded=StateLoadOption::read_only(manifest["state"].as_str().unwrap()).load()?;loaded.state.activate_loaded_integrand_backends(false)?;let model=&loaded.state.model;let integrand=loaded.state.process_list.get_integrand_mut(0,"NNLO")?;let original=integrand.get_settings().clone();let mut reports=Vec::new();
 for seed in manifest["paired_seeds"].as_array().unwrap(){for mode in ["optimized_lmb","direct_h_p1","direct_h_p2","direct_h_p2_plus_lmb"]{
  let name=format!("{mode}_seed{seed}");let workspace=format!("{}/{name}/workspace",args[1]);let bytes=fs::read(format!("{workspace}/state/integration_state.bin"))?;let (state,consumed)=bincode::decode_from_slice::<IntegrationState,_>(&bytes,bincode::config::standard())?;ensure!(consumed==bytes.len(),"trailing checkpoint bytes");ensure!(state.iter==1&&state.num_points==2048,"only fresh first iteration replay supported: {} {}",state.iter,state.num_points);ensure!(state.all_integrals.len()==1,"one integrand slot required");
  let card=fs::read_to_string(format!("{workspace}/integrands/epem_a_tth@NNLO/settings.toml"))?;*integrand.get_mut_settings()=SetArgs::String{string:card}.merge_figment(Figment::from(Serialized::defaults(&original)))?.extract()?;
  std::thread::scope(|scope|->Result<()>{std::thread::Builder::new().stack_size(128*1024*1024).spawn_scoped(scope,||integrand.warm_up(model))?.join().map_err(|_|eyre!("warmup panic"))?})?;
  let mut maxima=Vec::new();for (phase,acc) in [("re",&state.all_integrals[0].re),("im",&state.all_integrals[0].im)]{for (sign,value,sample) in [("positive",acc.max_eval_positive,&acc.max_eval_positive_xs),("negative",acc.max_eval_negative,&acc.max_eval_negative_xs)]{
   let Some(sample)=sample else{continue};let (ids,cube,factors)=path(sample)?;ensure!(ids.len()==2&&ids[0]==0&&cube.len()==12,"unexpected selection path {ids:?}");
   let mut batch=integrand.evaluate_samples_raw(model,std::slice::from_ref(sample),0,false,false,Complex::new(F(0.),F(0.)))?;let r=batch.samples.remove(0);ensure!(!r.evaluation_metadata.is_nan,"invalid maximum replay");let scalar=if phase=="re"{r.integrand_result.re.0}else{r.integrand_result.im.0};let weighted=scalar*r.parameterization_jacobian.map(|v|v.0).unwrap_or(1.)*sample.get_weight().0;let relative=(weighted-value.0).abs()/value.0.abs().max(f64::MIN_POSITIVE);ensure!(relative<1e-10,"{name} {phase} {sign} maximum mismatch {weighted} vs{value},relative{relative}");
   let ProcessIntegrand::CrossSection(p)=&*integrand else{return Err(eyre!("cross section expected"))};ensure!(p.data.graph_terms.len()==1&&p.data.graph_terms[0].selected_production_orientation_keys().len()==936,"full936 required");let term=&p.data.graph_terms[0];let precision=r.evaluation_metadata.stability_results.last().ok_or_else(||eyre!("missing replay precision"))?.precision;
   let geometry=match precision{Precision::Double=>mapped::<f64>(term,ids[1],&cube)?,Precision::Quad=>mapped::<QuadFloat>(term,ids[1],&cube)?,Precision::Arb=>mapped::<ArbPrec>(term,ids[1],&cube)?};
   maxima.push(json!({"phase":phase,"sign":sign,"stored_maximum":value.0,"replayed_maximum":weighted,"relative_difference":relative,"complete_sample":sample,"sample_weight":sample.get_weight().0,"conditional_factors":factors,"evaluation":r,"map":geometry,"precision_note":"stability history belongs to replay, original checkpoint does not retain original selected precision"}));
  }}
  let integral=&state.all_integrals[0];let stats=|a:&symbolica::numerical_integration::StatisticsAccumulator<F<f64>>|json!({"avg":a.avg.0,"err":a.err.0,"max_positive":a.max_eval_positive.0,"max_negative":a.max_eval_negative.0,"processed_samples":a.processed_samples,"zero_evaluations":a.num_zero_evaluations});
  let row=json!({"mode":mode,"seed":seed,"num_points":state.num_points,"iter":state.iter,"elapsed_seconds":state.elapsed_seconds,"n_cores":state.n_cores,"stats":state.stats,"slot_stats":state.slot_stats,"re":stats(&integral.re),"im":stats(&integral.im),"absolute_re":stats(&integral.absolute_re),"absolute_im":stats(&integral.absolute_im),"maxima":maxima});fs::write(format!("{}/{name}.json",args[2]),serde_json::to_string_pretty(&row)?)?;println!("replayed {name}");reports.push(row);
 }}
 fs::write(format!("{}/summary.json",args[2]),serde_json::to_string_pretty(&json!({"runs":reports,"elapsed_seconds":start.elapsed().as_secs_f64()}))?)?;Ok(())
}
